 const std::map<std::string,unsigned> errors{{"#NULL!",0},{"#DIV/0!",7},{"#VALUE!",15},{"#REF!",23},{"#NAME?",29},{"#NUM!",36},{"#N/A",42}};if(const auto found=errors.find(upper);found!=errors.end())return {Value::error,0,found->second,{}};
