FormulaReference viewReference(const std::string& text,bool single,bool selection=false){
 const auto references=formulaReferences("="+text);if(references.size()!=1||references[0].start!=1||references[0].length!=text.size()||references[0].external||!references[0].sheet.empty())throw std::runtime_error("Invalid BIFF worksheet view reference");auto reference=references[0];if(single&&(reference.row1!=reference.row2||reference.col1!=reference.col2))throw std::runtime_error("Invalid BIFF worksheet view cell");
 // Only an explicitly selected entire modern axis can be reduced to BIFF8.
 // A finite cell or range outside the legacy grid must never be truncated.
 if(selection&&reference.row1==1&&reference.row2==MaxRows)reference.row2=65536;
 if(selection&&reference.col1==1&&reference.col2==MaxColumns)reference.col2=256;
 if(reference.row2>65536||reference.col2>256)throw std::runtime_error("Worksheet view lies outside BIFF8 bounds");return reference;
}
struct SheetView {FormulaReference active,top;std::vector<FormulaReference> ranges;unsigned zoom=100,activeRange=0;};
